package com.danawa.search.analysis.dict

import org.apache.logging.log4j.LogManager
import java.io.*

abstract class SourceDictionary<E>(
    protected var ignoreCase: Boolean,
    var label: String?,
    var seq: Int,
    var tokenType: String?,
    var type: ProductNameDictionary.Type
) : ReloadableDictionary, WritableDictionary, ReadableDictionary {

    fun ignoreCase(): Boolean = ignoreCase
    fun label(): String? = label
    fun seq(): Int = seq
    fun tokenType(): String? = tokenType
    fun ignoreCase(ignoreCase: Boolean) { this.ignoreCase = ignoreCase }
    fun type(): ProductNameDictionary.Type = this.type

    fun loadSource(file: File) {
        var `is`: InputStream? = null
        try {
            `is` = FileInputStream(file)
            loadSource(`is`)
        } catch (e: FileNotFoundException) {
            logger.error("사전소스파일을 찾을수 없습니다.", e)
        } finally {
            try { `is`?.close() } catch (ignore: IOException) { }
        }
    }

    fun loadSource(`is`: InputStream) {
        try {
            val br = BufferedReader(InputStreamReader(`is`, "utf-8"))
            var line: String?
            while (br.readLine().also { line = it } != null) {
                addSourceLineEntry(line!!)
            }
        } catch (e: IOException) {
            logger.error("", e)
        }
    }

    fun addEntry(keyword: CharSequence?, values: Array<Any>?) {
        addEntry(keyword, values, null)
    }

    abstract fun addEntry(keyword: CharSequence?, values: Array<Any>?, columnSettingList: List<E>?)

    abstract fun addSourceLineEntry(line: CharSequence)

    companion object {
        @JvmStatic
        protected val logger = LogManager.getLogger(SourceDictionary::class.java)
    }
}

